1	// The constructor keeps a public named param (`localAuthentication`)
2	// distinct from the private field it initializes, matching
3	// `session_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:async';
6	
7	import 'package:fpdart/fpdart.dart';
8	import 'package:flutter/widgets.dart';
9	import 'package:flutter_secure_storage/flutter_secure_storage.dart';
10	import 'package:local_auth/local_auth.dart';
11	
12	import '../../../../core/failure/failure.dart';
13	import '../../domain/entities/vault_status.dart';
14	import '../../domain/repositories/vault_repository.dart';
15	import '../../domain/vault_idle_timeout.dart';
16	
17	/// Owns the one broadcast [VaultStatus] stream the epic's AD-14 seam
18	/// requires. Covers the I/O matrix (spec-2-1 + spec-2-2 + spec-2-3):
19	/// - biometrics succeed -> [VaultStatus.unlocked] emitted, `Right(unit)`.
20	/// - biometrics fail/cancelled/unavailable (`authenticate()` returns
21	///   `false`, or throws `LocalAuthException`, including any OS lockout) ->
22	///   status stays [VaultStatus.locked], `Left(Failure.
23	///   malformedResponse(...))` — every one of those cases routes the caller
24	///   to [submitPin] next (spec-2-2), with no code-specific branch needed
25	///   here since the generic catches below already cover lockout.
26	/// - [submitPin], no PIN stored yet -> stores it, [VaultStatus.unlocked]
27	///   emitted, `Right(unit)`.
28	/// - [submitPin], stored PIN matches -> [VaultStatus.unlocked] emitted,
29	///   `Right(unit)`.
30	/// - [submitPin], stored PIN mismatch -> status stays locked, `Left(Failure.
31	///   malformedResponse(...))`, always retryable (no attempt cap).
32	/// - spec-2-3: backgrounded (`AppLifecycleState.paused`) for >= 5 minutes
33	///   while [VaultStatus.unlocked], then resumed -> [VaultStatus.locked]
34	///   emitted via [didChangeAppLifecycleState]; below that threshold, or
35	///   while already locked, no emission at all.
36	///
37	/// Zero network calls anywhere in this class (Boundaries: "Vault makes zero
38	/// network calls") and never produces [Failure.authInvalid] (Boundaries:
39	/// reserved for password login) — every failure branch below maps only to
40	/// [Failure.malformedResponse]. The PIN is compared as a plain string
41	/// (Design Notes: `flutter_secure_storage` already encrypts at rest;
42	/// `package:crypto` isn't a pinned dependency) stored under [_pinStorageKey]
43	/// via the same [FlutterSecureStorage] instance
44	/// `SecureStorageAccessTokenProvider` uses for the access/refresh tokens.
45	class VaultRepositoryImpl
46	    with WidgetsBindingObserver
47	    implements VaultRepository {
48	  VaultRepositoryImpl({
49	    required LocalAuthentication localAuthentication,
50	    required FlutterSecureStorage secureStorage,
51	    DateTime Function() now = DateTime.now,
52	  }) : _localAuthentication = localAuthentication,
53	       _secureStorage = secureStorage,
54	       _now = now {
55	    // Story 2.3 — observes app-lifecycle transitions directly so idle
56	    // re-lock works with zero DI changes and zero new VaultRepository
57	    // methods. Removed in dispose() below. Safe only because
58	    // `WidgetsFlutterBinding.ensureInitialized()` (or an equivalent, e.g.
59	    // `TestWidgetsFlutterBinding.ensureInitialized()` in tests) must
60	    // already have run before this constructor executes — true today
61	    // because `get_it` constructs this lazily, well after `main()`'s own
62	    // binding initialization.
63	    //
64	    // Review finding: `WidgetsBinding.instance` itself throws an opaque
65	    // Flutter-internal assertion if no binding exists yet — caught here and
66	    // rethrown with a message that names the actual root cause, so any
67	    // future call site that breaks this ordering fails clearly instead of
68	    // opaquely. Review finding: `BindingBase.checkInstance`'s own null-
69	    // binding check is entirely wrapped in `assert(() {...})` (its doc
70	    // comment: "In release mode it always returns the argument"), so a
71	    // release build never actually throws `FlutterError` here — it
72	    // silently returns `null` typed as non-nullable instead, and the very
73	    // next call fails with an unrelated, uncaught error. Catching `Object`
74	    // (not just `FlutterError`) makes this guard work the same way in
75	    // every build mode, debug or release.
76	    try {
77	      WidgetsBinding.instance.addObserver(this);
78	    } on Object catch (error) {
79	      throw StateError(
80	        'VaultRepositoryImpl requires WidgetsFlutterBinding.ensureInitialized() '
81	        '(or TestWidgetsFlutterBinding.ensureInitialized() in tests) to run '
82	        'before construction. Original error: $error',
83	      );
84	    }
85	  }
86	
87	  static const _pinStorageKey = 'vault_pin';
88	
89	  final LocalAuthentication _localAuthentication;
90	  final FlutterSecureStorage _secureStorage;
91	  final DateTime Function() _now;
92	  final StreamController<VaultStatus> _statusController =
93	      StreamController<VaultStatus>.broadcast();
94	
95	  /// Incremented at the start of every [submitPin] call. Review finding:
96	  /// the UI's own `.timeout()` only stops it from *waiting* — the call
97	  /// here keeps running — so a user-triggered retry after that UI timeout
98	  /// could otherwise race a still-in-flight earlier call against the same
99	  /// storage key, or let its stale result emit [VaultStatus.unlocked]
100	  /// behind the newer attempt's back. A call whose captured generation no
101	  /// longer matches this field by the time its [_secureStorage.read]
102	  /// resolves is superseded and must not mutate storage or emit.
103	  int _submitPinGeneration = 0;
104	
105	  /// Set on `AppLifecycleState.paused`, read and cleared on
106	  /// `AppLifecycleState.resumed` (Boundaries: `inactive`/`hidden` are not
107	  /// "backgrounded" on their own — only this pair bounds iOS's actual
108	  /// background/foreground transition). `null` means either the app has
109	  /// never been backgrounded, or the last `paused`->`resumed` cycle already
110	  /// consumed it.
111	  DateTime? _backgroundedAt;
112	
113	  /// The last status emitted. Starts at [VaultStatus.locked] — not
114	  /// nullable, see [VaultStatus]'s own doc — so [currentStatus] is correct
115	  /// synchronously from construction, with no async warm-up step.
116	  VaultStatus _lastStatus = VaultStatus.locked;
117	
118	  @override
119	  VaultStatus get currentStatus => _lastStatus;
120	
121	  @override
122	  Stream<VaultStatus> get statusStream {
123	    // Same `Stream.multi` replay-to-late-listeners rationale as
124	    // `SessionRepositoryImpl.statusStream`: a listener that subscribes
125	    // after construction (but before any [authenticate] call) still
126	    // immediately sees the cached [_lastStatus] ([VaultStatus.locked])
127	    // rather than nothing until the next emission.
128	    return Stream<VaultStatus>.multi((controller) {
129	      controller.add(_lastStatus);
130	      final subscription = _statusController.stream.listen(
131	        controller.add,
132	        onError: controller.addError,
133	        onDone: controller.close,
134	      );
135	      controller.onCancel = subscription.cancel;
136	    }, isBroadcast: true);
137	  }
138	
139	  void _emit(VaultStatus status) {
140	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
141	    // an in-flight `authenticate()` call — mirrors
142	    // `SessionRepositoryImpl._emit`'s own guard.
143	    if (_statusController.isClosed) {
144	      return;
145	    }
146	    if (status == VaultStatus.unlocked) {
147	      // Review finding: without this, a biometric/PIN call that resolves
148	      // while the app is still backgrounded (persistAcrossBackgrounding:
149	      // true covers exactly this) leaves the *original* `_backgroundedAt`
150	      // in place; if `resumed` then arrives >= 5 minutes after that
151	      // original timestamp, the idle check below immediately re-locks the
152	      // vault the instant it was unlocked. Any unlock always starts the
153	      // idle clock fresh instead.
154	      _backgroundedAt = null;
155	    }
156	    _lastStatus = status;
157	    _statusController.add(status);
158	  }
159	
160	  @override
161	  void didChangeAppLifecycleState(AppLifecycleState state) {
162	    // Story 2.3's I/O & Edge-Case Matrix, exactly:
163	    // - `paused` -> record the backgrounded timestamp (only meaningful read
164	    //   on the next `resumed`).
165	    // - `resumed` with no prior `paused` recorded -> no-op (e.g. the very
166	    //   first lifecycle callback ever observed).
167	    // - `resumed` with elapsed time < 5 minutes -> no-op, `currentStatus`
168	    //   stays whatever it was.
169	    // - `resumed` with elapsed time >= 5 minutes AND `currentStatus` is
170	    //   currently `unlocked` -> emit `locked` exactly once; never
171	    //   redundantly if already `locked` (no duplicate emission).
172	    // `inactive`/`hidden` are intentionally ignored (Boundaries) — they
173	    // don't bound the real background/foreground transition on their own.
174	    if (state == AppLifecycleState.paused) {
175	      // Review finding: `??=` (not `=`) — keeps the *earliest* timestamp if
176	      // `paused` ever fires twice before a `resumed` consumes it, so a
177	      // lifecycle quirk can't reset the idle clock to a later start and
178	      // undercount real elapsed background time.
179	      _backgroundedAt ??= _now();
180	      return;
181	    }
182	    if (state == AppLifecycleState.resumed) {
183	      final backgroundedAt = _backgroundedAt;
184	      _backgroundedAt = null;
185	      if (backgroundedAt == null) {
186	        return;
187	      }
188	      final elapsed = _now().difference(backgroundedAt);
189	      if (elapsed >= vaultIdleTimeout && _lastStatus == VaultStatus.unlocked) {
190	        _emit(VaultStatus.locked);
191	      }
192	    }
193	  }
194	
195	  @override
196	  Future<Either<Failure, Unit>> authenticate() async {
197	    try {
198	      // `biometricOnly: true` (Boundaries/Design Notes) — never lets the
199	      // OS's own device-passcode UI satisfy this call, which would bypass
200	      // Cerne's own PIN screen (Story 2.2) entirely.
201	      // `persistAcrossBackgrounding: true` so a backgrounding mid-prompt
202	      // (e.g. an incoming call) retries on foreground instead of failing
203	      // outright.
204	      final success = await _localAuthentication.authenticate(
205	        localizedReason: 'Autentique-se para acessar o Cerne',
206	        biometricOnly: true,
207	        persistAcrossBackgrounding: true,
208	      );
209	      if (success) {
210	        _emit(VaultStatus.unlocked);
211	        return right(unit);
212	      }
213	      // A `false` result (declined/unavailable, no exception) — status
214	      // stays `locked`; never `Failure.authInvalid` (Boundaries: reserved
215	      // for password login).
216	      return left(
217	        const Failure.malformedResponse(
218	          message: 'Biometric authentication was not successful',
219	        ),
220	      );
221	    } on LocalAuthException catch (error) {
222	      // Covers cancellation, no enrolled biometrics, hardware unavailable,
223	      // etc. (RNF09: never let a platform exception escape unmapped).
224	      return left(Failure.malformedResponse(message: error.toString()));
225	    } catch (error) {
226	      // Any other thrown platform exception (e.g. the plugin's channel
227	      // itself failing) must never escape unmapped either (RNF09) — fail
228	      // closed, same as the documented `LocalAuthException` branch above,
229	      // mirroring `SessionRepositoryImpl.restoreSession()`'s own plain
230	      // `catch`.
231	      return left(Failure.malformedResponse(message: error.toString()));
232	    }
233	  }
234	
235	  @override
236	  Future<Either<Failure, Unit>> submitPin(String pin) async {
237	    final generation = ++_submitPinGeneration;
238	    try {
239	      final storedPin = await _secureStorage.read(key: _pinStorageKey);
240	      if (generation != _submitPinGeneration) {
241	        // A newer `submitPin` call started while this one was still
242	        // awaiting `read` (e.g. the caller's own UI timed out and the user
243	        // retried) — never let this superseded attempt write a possibly
244	        // stale PIN or emit `unlocked` behind the newer attempt's back.
245	        return left(
246	          const Failure.malformedResponse(
247	            message: 'Superseded by a newer PIN attempt',
248	          ),
249	        );
250	      }
251	      // No PIN-creation screen exists anywhere in `docs/input/` (Design
252	      // Notes) — the first ever `submitPin` call sets the stored PIN
253	      // instead of comparing against one.
254	      if (storedPin == null) {
255	        await _secureStorage.write(key: _pinStorageKey, value: pin);
256	        // Review finding: the check right after `read()` above only
257	        // guards against a slow `read()` — a call whose own `write()` is
258	        // the slow step could pass that earlier check, then still land
259	        // here and unconditionally emit `unlocked` after being superseded
260	        // by a second call that finished first. Re-checked here, right
261	        // before emitting, closes that same gap for a slow `write()`.
262	        if (generation != _submitPinGeneration) {
263	          return left(
264	            const Failure.malformedResponse(
265	              message: 'Superseded by a newer PIN attempt',
266	            ),
267	          );
268	        }
269	        _emit(VaultStatus.unlocked);
270	        return right(unit);
271	      }
272	      if (storedPin == pin) {
273	        _emit(VaultStatus.unlocked);
274	        return right(unit);
275	      }
276	      // Mismatch — status stays `locked`, no attempt cap (Boundaries: "PIN
277	      // has no attempt cap — always retryable"); never `Failure.authInvalid`
278	      // (reserved for password login), same rationale as `authenticate()`.
279	      return left(
280	        const Failure.malformedResponse(
281	          message: 'PIN did not match the stored PIN',
282	        ),
283	      );
284	    } catch (error) {
285	      // A thrown platform exception from the secure-storage channel must
286	      // never escape unmapped either (RNF09) — fail closed, same as
287	      // `authenticate()`'s own plain `catch`.
288	      return left(Failure.malformedResponse(message: error.toString()));
289	    }
290	  }
291	
292	  @override
293	  void lock() => _emit(VaultStatus.locked);
294	
295	  @override
296	  Future<void> dispose() async {
297	    WidgetsBinding.instance.removeObserver(this);
298	    await _statusController.close();
299	  }
300	}
