1	// The constructor keeps a public named param (`remoteDataSource`) distinct
2	// from the private field it initializes, matching `vault_repository_impl.
3	// dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:async';
6	
7	import 'package:fpdart/fpdart.dart';
8	
9	import '../../../../core/failure/failure.dart';
10	import '../../domain/repositories/account_settings_repository.dart';
11	import '../datasources/account_remote_data_source.dart';
12	
13	/// Owns the one broadcast `biometricEnabled` stream Story 2.4's AD-14-style
14	/// seam requires. Covers the I/O & Edge-Case Matrix exactly:
15	/// - boot fetch resolves `false`/`true` -> [currentBiometricEnabled]/
16	///   [biometricEnabledStream] updated to that value.
17	/// - boot fetch fails -> swallowed, [currentBiometricEnabled] unchanged.
18	/// - [setBiometricEnabled] -> flips immediately (optimistic), PATCH fires;
19	///   success leaves it flipped, failure reverts it and returns `Left`.
20	class AccountSettingsRepositoryImpl implements AccountSettingsRepository {
21	  AccountSettingsRepositoryImpl({
22	    required AccountRemoteDataSource remoteDataSource,
23	  }) : _remoteDataSource = remoteDataSource;
24	
25	  final AccountRemoteDataSource _remoteDataSource;
26	  final StreamController<bool> _controller = StreamController<bool>.broadcast();
27	
28	  /// Starts `true` (never `null`, Boundaries) — the single source of truth
29	  /// for both the vault gate and the Configurações toggle.
30	  bool _currentValue = true;
31	
32	  /// spec-8-3 — starts `''` (Boundaries: "default ''"), set only from
33	  /// [fetchBiometricEnabled]'s own success branch (piggybacking on that
34	  /// call's response — no new network call) or from a successful
35	  /// [setDisplayName].
36	  String _currentDisplayName = '';
37	
38	  /// spec-8-3 — same "starts `''`, boot-fetch piggyback" shape as
39	  /// [_currentDisplayName]; never written anywhere else — `PATCH
40	  /// /account/settings` rejects `email` (contract summary: "email is
41	  /// rejected").
42	  String _currentEmail = '';
43	
44	  /// Review finding: without this, two overlapping calls — a double-tap
45	  /// toggle, or a boot [fetchBiometricEnabled] resolving while a
46	  /// [setBiometricEnabled] call is still in flight — let a stale call's
47	  /// revert/confirm stomp a newer call's already-settled value, because
48	  /// each call's own PATCH round-trip resolves independently of the
49	  /// others. Mirrors `VaultRepositoryImpl._submitPinGeneration`'s same
50	  /// fix for the exact same class of bug: every call captures the
51	  /// generation current at its OWN start; only the call whose captured
52	  /// generation still matches this field once its PATCH resolves is
53	  /// allowed to mutate [_currentValue]/emit — every other (superseded)
54	  /// call's result is discarded.
55	  int _generation = 0;
56	
57	  /// spec-8-3 — [setDisplayName]'s own generation guard, same shape as
58	  /// [_generation] but kept separate (Boundaries): a name write and a
59	  /// biometric toggle/fetch are independent calls that must never
60	  /// supersede each other's in-flight state.
61	  int _nameGeneration = 0;
62	
63	  @override
64	  bool get currentBiometricEnabled => _currentValue;
65	
66	  @override
67	  String get currentDisplayName => _currentDisplayName;
68	
69	  @override
70	  String get currentEmail => _currentEmail;
71	
72	  @override
73	  Stream<bool> get biometricEnabledStream {
74	    // Same `Stream.multi` replay-to-late-listeners rationale as
75	    // `VaultRepositoryImpl.statusStream`/`SessionRepositoryImpl.
76	    // statusStream`: a listener that subscribes after construction still
77	    // immediately sees the cached current value rather than nothing until
78	    // the next emission.
79	    return Stream<bool>.multi((controller) {
80	      controller.add(_currentValue);
81	      final subscription = _controller.stream.listen(
82	        controller.add,
83	        onError: controller.addError,
84	        onDone: controller.close,
85	      );
86	      controller.onCancel = subscription.cancel;
87	    }, isBroadcast: true);
88	  }
89	
90	  void _emit(bool value) {
91	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
92	    // an in-flight `fetchBiometricEnabled()`/`setBiometricEnabled()` call —
93	    // mirrors `VaultRepositoryImpl._emit`'s own guard.
94	    if (_controller.isClosed) {
95	      return;
96	    }
97	    _currentValue = value;
98	    _controller.add(value);
99	  }
100	
101	  @override
102	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async {
103	    final generation = ++_generation;
104	    // Code-review patch (spec-8-3): captured so the piggybacked
105	    // `displayName`/`email` write below can detect a `setDisplayName`
106	    // call that started *after* this fetch — without this, a stale fetch
107	    // resolving after a concurrent name save already succeeded would
108	    // silently overwrite the just-saved name/email back to this fetch's
109	    // own (older) values, the same class of bug `_generation` already
110	    // guards against for `currentBiometricEnabled`.
111	    final nameGeneration = _nameGeneration;
112	    final result = await _remoteDataSource.fetchSettings();
113	    return result.match(
114	      (failure) {
115	        // Swallowed, fire-and-forget like `SessionRepository.
116	        // restoreSession()` — `currentBiometricEnabled` stays exactly as it
117	        // was (I/O matrix: "Boot fetch fails").
118	        return left(failure);
119	      },
120	      (dto) {
121	        // spec-8-3 — same response, no new network call (Boundaries):
122	        // `_currentDisplayName`/`_currentEmail` piggyback on this already
123	        // in-flight fetch's own DTO. Code-review patch: only applied if no
124	        // `setDisplayName` call has started since this fetch began — a
125	        // concurrent name save that already resolved owns the name/email
126	        // fields from here on, and this now-stale piggyback must not
127	        // clobber it. Review finding: evaluated independently of (and
128	        // before) the `_generation` check below — a fetch superseded only
129	        // on its *biometric-toggle* generation (e.g. the double boot-time
130	        // call in `main.dart`/`CerneApp.initState()`) still carries a
131	        // perfectly valid, non-conflicting `displayName`/`email` that must
132	        // not be thrown away along with the discarded `biometricEnabled`
133	        // result.
134	        if (nameGeneration == _nameGeneration) {
135	          _currentDisplayName = dto.displayName;
136	          _currentEmail = dto.email;
137	        }
138	        // Review finding: a `setBiometricEnabled` call that started after
139	        // this fetch (and has therefore already bumped `_generation`) has
140	        // superseded it — this fetch's now-stale read must not clobber
141	        // whatever that newer call already settled on, and must not report
142	        // success either, since its result was discarded (mirrors
143	        // `setBiometricEnabled`'s own stale-generation branch).
144	        if (generation != _generation) {
145	          return left(
146	            const Failure.malformedResponse(
147	              message: AccountSettingsRepository.supersededMessage,
148	            ),
149	          );
150	        }
151	        _emit(dto.biometricEnabled);
152	        return right(unit);
153	      },
154	    );
155	  }
156	
157	  @override
158	  Future<Either<Failure, Unit>> setDisplayName(String name) async {
159	    final generation = ++_nameGeneration;
160	    // spec-8-3 — not optimistic (Boundaries): unlike
161	    // `setBiometricEnabled`, `_currentDisplayName` only changes once the
162	    // PATCH below actually succeeds.
163	    final result = await _remoteDataSource.updateDisplayName(name);
164	    if (generation != _nameGeneration) {
165	      // Superseded by a newer overlapping `setDisplayName` call — same
166	      // "discard, don't clobber" rationale as `setBiometricEnabled`'s own
167	      // stale-generation branch, just on its own, separate counter.
168	      return left(
169	        const Failure.malformedResponse(
170	          message: AccountSettingsRepository.supersededMessage,
171	        ),
172	      );
173	    }
174	    return result.match((failure) => left(failure), (dto) {
175	      // Code-review patch: the response's own echoed `displayName` is the
176	      // source of truth, not the local `name` parameter — any backend-side
177	      // normalization (trimming, casing, etc.) must be reflected locally
178	      // rather than assuming the server stored exactly what was sent.
179	      _currentDisplayName = dto.displayName;
180	      return right(unit);
181	    });
182	  }
183	
184	  @override
185	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
186	    final generation = ++_generation;
187	    final previous = _currentValue;
188	    // Optimistic flip — switches immediately, before the PATCH call below
189	    // even starts (RNF01, <100ms; Boundaries). Always applied: this call
190	    // is, by construction, the newest one at the moment it starts.
