9	/// Posts via the shared `ApiClient`, mirroring
10	/// `auth_remote_data_source.dart`'s pattern.
11	class AccountRemoteDataSource {
12	  AccountRemoteDataSource(this._apiClient);
13	
14	  final ApiClient _apiClient;
15	
16	  /// Called with `{}` to read the current settings without changing
17	  /// anything (Boundaries: "`PATCH /account/settings` ... called empty to
18	  /// read").
19	  Future<Either<Failure, AccountSettingsDto>> fetchSettings() =>
20	      _patch(const {});
21	
22	  /// Called with exactly `{"biometricEnabled": enabled}` to write — never
23	  /// `displayName`/`persona` (Epic 8's scope, Boundaries).
24	  Future<Either<Failure, AccountSettingsDto>> updateBiometricEnabled(
25	    bool enabled,
26	  ) => _patch({'biometricEnabled': enabled});
27	
28	  /// spec-8-3 — called with exactly `{"displayName": name}` to write the
29	  /// profile name, mirroring [updateBiometricEnabled]'s own shape (Code
30	  /// Map: "mirrors updateBiometricEnabled").
31	  Future<Either<Failure, AccountSettingsDto>> updateDisplayName(String name) =>
32	      _patch({'displayName': name});
33	
34	  /// Story 8.5 — `account-delete` (`DELETE /account`), bearerAuth, exactly
35	  /// `{"confirmation": "DELETE"}` (Boundaries/Code Map). No DTO shape worth
36	  /// decoding — same "only whether the call itself succeeded matters"
37	  /// rationale as `AuthRemoteDataSource.logout()`'s own `{data: {ok:
38	  /// true}}` response, mapped straight to `Right(unit)`, discarding the
39	  /// body.
40	  Future<Either<Failure, Unit>> deleteAccount() async {
41	    final result = await _apiClient.delete(
42	      'account-delete',
43	      data: const {'confirmation': 'DELETE'},
44	    );
45	    return result.map((_) => unit);
46	  }
47	
48	  Future<Either<Failure, AccountSettingsDto>> _patch(
49	    Map<String, dynamic> data,
50	  ) async {
51	    final result = await _apiClient.patch(
52	      'account-settings-update',
53	      data: data,
54	    );
55	    return result.flatMap((json) {
56	      try {
57	        final responseData = json['data'] as Map<String, dynamic>;
58	        return right(AccountSettingsDto.fromJson(responseData));
59	      } catch (error) {
60	        // A 200 response that doesn't match the expected shape is a
61	        // client-side parse failure, never a backend-sent code — maps to
62	        // the local-only `malformedResponse` (RNF09: no exception escapes).
63	        return left(Failure.malformedResponse(message: error.toString()));
64	      }
65	    });
66	  }
67	}
